operation.add:
public function addSchema(array $schema) {
	if ($schema) {
		$this->schemas[] = \Schemaorg\Builder::encode($schema);
	}
}

public function getSchemas() {
	return $this->schemas;
}

{% for schema in schemas %}
<script type="application/ld+json">{{ schema }}</script>
{% endfor %}

public function getStructuredDataSummary($product_id) {
	$special = $this->db->query("SELECT date_end FROM " . DB_PREFIX . "product_special ps WHERE ps.product_id = '" . (int)$product_id . "' AND ps.customer_group_id = '" . (int)$this->config->get('config_customer_group_id') . "' AND ((ps.date_start = '0000-00-00' OR ps.date_start < NOW()) AND (ps.date_end = '0000-00-00' OR ps.date_end > NOW())) ORDER BY ps.priority ASC, ps.price ASC LIMIT 1");

	$rating = $this->db->query("SELECT AVG(rating) AS rating, COUNT(*) AS total FROM " . DB_PREFIX . "review WHERE product_id = '" . (int)$product_id . "' AND status = '1'");

	return array(
		'special_date_end' => $special->num_rows ? $special->row['date_end'] : '',
		'rating'           => (float)$rating->row['rating'],
		'review_count'     => (int)$rating->row['total']
	);
}

$schema_summary = $this->model_catalog_product->getStructuredDataSummary($product_info['product_id']);
$schema_currency = $this->session->data['currency'];
$schema_price = $this->tax->calculate((float)$product_info['special'] ? $product_info['special'] : $product_info['price'], $product_info['tax_class_id'], $this->config->get('config_tax'));
$schema_popup_width = $this->config->get('theme_' . $this->config->get('config_theme') . '_image_popup_width');
$schema_popup_height = $this->config->get('theme_' . $this->config->get('config_theme') . '_image_popup_height');

$schema_images = array();

if ($product_info['image']) {
	$schema_images[] = $this->model_tool_image->resize($product_info['image'], $schema_popup_width, $schema_popup_height);
}

foreach ($results as $schema_image) {
	$schema_images[] = $this->model_tool_image->resize($schema_image['image'], $schema_popup_width, $schema_popup_height);
}

$schema_reviews = array();

if ($this->config->get('config_review_status') && $schema_summary['review_count']) {
	foreach ($this->model_catalog_review->getReviewsByProductId($product_info['product_id'], 0, \Schemaorg\Builder::MAX_REVIEWS) as $schema_review) {
		$schema_reviews[] = array(
			'author' => $schema_review['author'],
			'rating' => $schema_review['rating'],
			'date'   => $schema_review['date_added'],
			'body'   => $schema_review['text']
		);
	}
}

$this->document->addSchema(\Schemaorg\Builder::product(array(
	'name'              => $product_info['name'],
	'url'               => $this->url->link('product/product', 'product_id=' . $product_info['product_id']),
	'description'       => $product_info['meta_description'] ? $product_info['meta_description'] : $product_info['description'],
	'images'            => $schema_images,
	'sku'               => $product_info['sku'],
	'mpn'               => $product_info['mpn'],
	'model'             => $product_info['model'],
	'gtin12'            => \Schemaorg\Builder::gtin($product_info['upc'], 12),
	'gtin13'            => \Schemaorg\Builder::gtin($product_info['ean'], 13),
	'brand_name'        => $product_info['manufacturer'],
	'price'             => $this->currency->format($schema_price, $schema_currency, '', false),
	'currency'          => $schema_currency,
	'in_stock'          => $product_info['quantity'] > 0,
	'price_valid_until' => (float)$product_info['special'] ? $schema_summary['special_date_end'] : '',
	'rating'            => $this->config->get('config_review_status') ? $schema_summary['rating'] : 0,
	'review_count'      => $this->config->get('config_review_status') ? $schema_summary['review_count'] : 0,
	'reviews'           => $schema_reviews
)));

$this->document->addSchema(\Schemaorg\Builder::breadcrumbs($data['breadcrumbs'], $this->config->get('config_name')));
